  var ps=document.getElementById(PFX+'-swatch');if(ps)ps.style.background=t.primary;
  var pn=document.getElementById(PFX+'-name');if(pn)pn.textContent=t.name;
  document.querySelectorAll('[data-'+PFX+'-key]').forEach(function(btn){
    var active=btn.getAttribute('data-'+PFX+'-key')===key;
