  ck.innerHTML='<path fill-rule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clip-rule="evenodd"/>';
  btn.appendChild(sw);btn.appendChild(nm);btn.appendChild(ck);
  btn.addEventListener('mouseenter',function(){if(btn.getAttribute('data-'+PFX+'-key')!==cur)btn.style.background='rgba(0,0,0,.04)';});
  btn.addEventListener('mouseleave',function(){if(btn.getAttribute('data-'+PFX+'-key')!==cur)btn.style.background='';});
  btn.addEventListener('click',function(e){e.stopPropagation();applyTheme(key);close();});
  return btn;
}
function mkGroup(title,entries,last){
