  h.textContent=title;wrap.appendChild(h);
  entries.forEach(function(e){wrap.appendChild(mkBtn(e[0],e[1]));});
  return wrap;
}
var groups={Corporate:[],Modern:[],Minimal:[]};
Object.keys(TP).forEach(function(k){var t=TP[k];var g=t.group||'Other';if(!groups[g])groups[g]=[];groups[g].push([k,t]);});
