panel.style.cssText='position:absolute;top:calc(100% + 6px);right:0;width:260px;background:#fff;border:1px solid rgba(0,0,0,.1);box-shadow:0 12px 36px rgba(0,0,0,.15);max-height:70vh;overflow-y:auto;display:none;';
order.forEach(function(g,i){if(groups[g]&&groups[g].length)panel.appendChild(mkGroup(g,groups[g],i===order.length-1));});
wrap.appendChild(pill);wrap.appendChild(panel);
if(!tp||tp.selectorEnabled!==false){
  document.body.appendChild(wrap);
  function positionWrap(){
    var nav=document.querySelector('header,.dnn-nav,nav[class*=nav]');
    var navH=nav?nav.getBoundingClientRect().bottom:0;
    wrap.style.top=Math.max(16,navH+8)+'px';
  }
  positionWrap();window.addEventListener('resize',positionWrap);setTimeout(positionWrap,500);
  function open(){isOpen=true;panel.style.display='block';chv.style.transform='rotate(180deg)';}
  function close(){isOpen=false;panel.style.display='none';chv.style.transform='';}
